#include <iostream>
#include <fstream>
#include <string>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <filesystem>
#include <functional>
#include <csignal>
#include <cstring>
#include <algorithm>
#include <chrono>

namespace fs = std::filesystem;

class CacheConfig {
public:
    static constexpr size_t MAX_ENTRY_SIZE = 64 * 1024 * 1024; // 64MB
    static constexpr const char* ALLOWED_EXTENSIONS[] = {".cache", ".tmp", ".dat"};
    static const std::string CACHE_ROOT;

    static bool isAllowedExtension(const std::string& path) {
        for (const auto& ext : ALLOWED_EXTENSIONS) {
            if (path.size() >= strlen(ext) && 
                path.compare(path.size() - strlen(ext), strlen(ext), ext) == 0) {
                return true;
            }
        }
        return false;
    }
};

const std::string CacheConfig::CACHE_ROOT = "/var/cache/distcache/";

class PathValidator {
public:
    static bool validateCachePath(const std::string& requested_path) {
        // Reject obvious traversal attempts
        if (requested_path.find("..") != std::string::npos) return false;
        if (requested_path.find("//") != std::string::npos) return false;
        if (requested_path[0] == '/') return false;

        // Build canonical path for validation
        std::string full_path = CacheConfig::CACHE_ROOT + requested_path;

        // Normalize the path
        std::string normalized = normalizePath(full_path);

        // Verify it stays within cache root
        if (normalized.compare(0, CacheConfig::CACHE_ROOT.size(), CacheConfig::CACHE_ROOT) != 0) {
            return false;
        }
        return true;
    }

private:
    static std::string normalizePath(const std::string& path) {
        std::vector<std::string> components;
        std::string current;
        for (char c : path) {
            if (c == '/') {
                if (!current.empty()) {
                    if (current == "..") {
                        if (!components.empty()) components.pop_back();
                    } else if (current != ".") {
                        components.push_back(current);
                    }
                    current.clear();
                }
            } else {
                current += c;
            }
        }
        if (!current.empty() && current != "." && current != "..") {
            components.push_back(current);
        }
        std::string result = "/";
        for (size_t i = 0; i < components.size(); ++i) {
            result += components[i];
            if (i < components.size() - 1) result += "/";
        }
        return result;
    }
};

class ShutdownHandler {
public:
    static std::atomic<bool> shutting_down;
    static std::mutex pending_writes_mutex;
    static std::vector<std::pair<std::string, std::vector<char>>> pending_writes;

    static void signalHandler(int sig) {
        shutting_down.store(true);
        flushPendingWrites();
    }

    static void flushPendingWrites() {
        std::lock_guard<std::mutex> lock(pending_writes_mutex);
        for (auto& [path, data] : pending_writes) {
            // During shutdown, bypass extension check to ensure data integrity
            // Path was already validated when queued
            std::string full_path = CacheConfig::CACHE_ROOT + path;
            fs::create_directories(fs::path(full_path).parent_path());
            std::ofstream out(full_path, std::ios::binary);
            if (out.is_open()) {
                out.write(data.data(), data.size());
            }
        }
        pending_writes.clear();
    }

    static void registerHandler() {
        std::signal(SIGTERM, signalHandler);
        std::signal(SIGINT, signalHandler);
    }
};

std::atomic<bool> ShutdownHandler::shutting_down{false};
std::mutex ShutdownHandler::pending_writes_mutex;
std::vector<std::pair<std::string, std::vector<char>>> ShutdownHandler::pending_writes;

class DistCacheClient {
public:
    DistCacheClient() {
        ShutdownHandler::registerHandler();
    }

    bool storeEntry(const std::string& key, const std::vector<char>& data) {
        if (data.size() > CacheConfig::MAX_ENTRY_SIZE) {
            return false;
        }

        // Validate the path
        if (!PathValidator::validateCachePath(key)) {
            return false;
        }

        if (ShutdownHandler::shutting_down.load()) {
            // Queue for flush - path already validated above
            std::lock_guard<std::mutex> lock(ShutdownHandler::pending_writes_mutex);
            ShutdownHandler::pending_writes.emplace_back(key, data);
            return true;
        }

        // Normal operation: validate extension
        if (!CacheConfig::isAllowedExtension(key)) {
            return false;
        }

        std::string full_path = CacheConfig::CACHE_ROOT + key;
        fs::create_directories(fs::path(full_path).parent_path());
        std::ofstream out(full_path, std::ios::binary);
        if (!out.is_open()) return false;
        out.write(data.data(), data.size());
        return true;
    }

    bool storeBatch(const std::vector<std::pair<std::string, std::vector<char>>>& entries) {
        bool all_ok = true;
        for (const auto& [key, data] : entries) {
            if (!storeEntry(key, data)) {
                all_ok = false;
            }
        }
        return all_ok;
    }
};

int main() {
    DistCacheClient client;

    // Example usage
    std::vector<char> sample_data = {'H', 'e', 'l', 'l', 'o'};
    client.storeEntry("region1/session.cache", sample_data);

    // Simulate graceful shutdown scenario
    std::this_thread::sleep_for(std::chrono::seconds(1));
    return 0;
}
